"""Build the standalone Earth Engine script with fixed PROSPECT-D leaf spectra."""
from pathlib import Path
import json
from absorption import table
import prosail
import numpy as np
from prosail.FourSAIL import verhoef_bimodal

root = Path(__file__).resolve().parent
_, rho, tau = prosail.run_prospect(1.5, 40, 8, 0, .015, .009, prospect_version="D")
idx = np.r_[220:271, 441:477]
constants = dict(rho=rho[idx].tolist(), tau=tau[idx].tolist(),
                 lidf=verhoef_bimodal(-.35, -.15, 18).tolist())
header = """// ACCLIM-RT Earth Engine retrieval library.
// Generated by rt/gee/build.py. Edit core.js and app.js, then rebuild.
// Fixed PROSPECT-D: N=1.5, Cab=40, Car=8, Cbrown=0, Cw=.015, Cm=.009.
// FourSAIL: spherical Verhoef LIDF (-.35,-.15), hotspot=.05.
// Spectral means over 620-670 and 841-876 nm, sampled at 1 nm.
// Equations follow Verhoef et al. 2007, doi:10.1109/TGRS.2007.895844.
// Numerical reference: jgomezdans/prosail 2.0.5, FourSAIL.py.
"""
text = header + "var RT_LEAF = " + json.dumps(constants, separators=(',', ':')) + ";\n"
text += 'var RT_PAR = ' + json.dumps(table(), separators=(',', ':')) + ';\n'
text += (root/'absorption.js').read_text(encoding='utf-8') + '\n'
text += (root/'core.js').read_text(encoding='utf-8') + "\n"
text += (root/'app.js').read_text(encoding='utf-8').split("if (typeof ui !== 'undefined') rtApp();")[0]
text += (root/'model_cover.js').read_text(encoding='utf-8')
app = root.parent.parent/'gee'/'Acclim_v2_shapefile.js'
begin, end = '// BEGIN ACCLIM-RT RETRIEVAL', '// END ACCLIM-RT RETRIEVAL'
before, existing = app.read_text(encoding='utf-8').split(begin)
_, after = existing.split(end)
full = before + begin + '\n' + text + '\n' + end + after
app.write_text(full, encoding='utf-8', newline='\n')
(root/'ACCLIM_RT_GEE.js').write_text(full, encoding='utf-8', newline='\n')
